import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Upload File","description":"","frontmatter":{"prev":{"text":"Field Response Action","link":"/documentation/form-fields/field-response-action"},"next":{"text":"Date Picker","link":"/documentation/field-types/date-picker"}},"headers":[],"relativePath":"documentation/field-types/upload-file.md","filePath":"documentation/field-types/upload-file.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/upload-file.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="upload-file" tabindex="-1">Upload File <a class="header-anchor" href="#upload-file" aria-label="Permalink to “Upload File”">​</a></h1><p>The <strong>Upload File</strong> field type automates local file selection and file uploads through web forms. It seamlessly handles native file dialogs across modern web platforms, including Google Forms, Microsoft Forms, government and banking portals, and custom web applications.</p><hr><h2 id="install-helper-program" tabindex="-1">Install Helper Program <a class="header-anchor" href="#install-helper-program" aria-label="Permalink to “Install Helper Program”">​</a></h2><p>Due to browser security sandboxes, browser extensions cannot directly interact with OS-level file dialogs without native messaging. The <a href="/documentation/program.html#download-and-install">Helper Program</a> is a lightweight local utility required to automatically select and upload files from your local file system.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The Helper Program must be installed and running on your computer for automated file selection and uploads to work.</p></div><h3 id="verifying-helper-program-connection" tabindex="-1">Verifying Helper Program Connection <a class="header-anchor" href="#verifying-helper-program-connection" aria-label="Permalink to “Verifying Helper Program Connection”">​</a></h3><p>In the field configuration sidebar, check the connection status banner:</p><img src="/image/upload-field-01.png" alt="Helper Program Upload Connection Check" style="max-width:420px;border-radius:8px;margin:16px 0;"><p>Click <strong>&quot;Click and Check File Upload Connection is Connected&quot;</strong> to verify active communication between the extension and the local helper program.</p><hr><h2 id="field-options" tabindex="-1">Field Options <a class="header-anchor" href="#field-options" aria-label="Permalink to “Field Options”">​</a></h2><p>The Upload File field provides granular controls for single, multiple, and batch folder uploads:</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Set File/Folder Base Path</strong></td><td>Specifies a root folder directory where your upload files reside.</td><td>No</td></tr><tr><td><strong>Base Path</strong></td><td>Full directory path to prepend to file names (e.g., <code>D:\\photos\\</code>).</td><td>When Base Path enabled</td></tr><tr><td><strong>Multiple File Upload</strong></td><td>Enables selecting and uploading multiple files in a single operation.</td><td>No</td></tr><tr><td><strong>Separator for Multiple File Upload</strong></td><td>Character used to separate multiple file names (e.g., <code>\\r\\n</code>, <code>,</code>, <code>;</code>).</td><td>When multiple files enabled</td></tr><tr><td><strong>Upload all files in a folder</strong></td><td>Automatically uploads all files contained inside the specified base folder.</td><td>No</td></tr><tr><td><strong>First check that the file exists in the PC, then select the file</strong></td><td>Verifies file existence on disk before attempting to open the dialog.</td><td>No</td></tr><tr><td><strong>Set the uploading browser window title name</strong></td><td>Customizes the target OS file dialog title (e.g., &quot;Open&quot; or &quot;Select File&quot;).</td><td>No</td></tr><tr><td><strong>Browser Window Title</strong></td><td>Custom title string matching the upload dialog window.</td><td>When title customization enabled</td></tr><tr><td><strong>File Name/Path</strong></td><td>Target file name or absolute path from the Excel column or default value.</td><td>Yes</td></tr></tbody></table><hr><h2 id="configuration-details" tabindex="-1">Configuration Details <a class="header-anchor" href="#configuration-details" aria-label="Permalink to “Configuration Details”">​</a></h2><h3 id="file-name-path" tabindex="-1">File Name and File Path Mapping <a class="header-anchor" href="#file-name-path" aria-label="Permalink to “File Name and File Path Mapping”">​</a></h3><p>You can specify target files using either relative file names (combined with a Base Path) or standalone absolute file paths:</p><h4 id="approach-a-file-name-with-base-path-recommended" tabindex="-1">Approach A: File Name with Base Path (Recommended) <a class="header-anchor" href="#approach-a-file-name-with-base-path-recommended" aria-label="Permalink to “Approach A: File Name with Base Path (Recommended)”">​</a></h4><p>When all files are stored in a common directory, configure the base path once in field options and specify only the file name in your Excel spreadsheet:</p><ul><li><strong>Base Path</strong>: <code>D:\\photos\\</code></li><li><strong>Excel Cell Value</strong>: <code>profile.jpg</code></li><li><strong>Resulting Full Path</strong>: <code>D:\\photos\\profile.jpg</code></li></ul><img src="/image/upload-field-02.png" alt="Set File/Folder Base Path Example" style="max-width:420px;border-radius:8px;margin:16px 0;"><h4 id="approach-b-full-absolute-path" tabindex="-1">Approach B: Full Absolute Path <a class="header-anchor" href="#approach-b-full-absolute-path" aria-label="Permalink to “Approach B: Full Absolute Path”">​</a></h4><p>If your files are located across different directories or drives, disable Base Path and provide the full absolute path in your spreadsheet:</p><ul><li><strong>Base Path</strong>: Disabled</li><li><strong>Excel Cell Value</strong>: <code>C:\\Users\\Username\\Documents\\contract.pdf</code></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Predefined variables such as <code>{$predefine_variable$}</code> and dynamic path templates can be used within the <code>File Name/Path</code> field.</p></div><hr><h3 id="set-file-folder-base-path" tabindex="-1">Set File/Folder Base Path <a class="header-anchor" href="#set-file-folder-base-path" aria-label="Permalink to “Set File/Folder Base Path”">​</a></h3><ul><li><strong>Purpose</strong>: Defines the parent directory where upload assets are stored.</li><li><strong>Format</strong>: <ul><li>Windows: <code>D:\\Documents\\Uploads\\</code> or <code>C:\\Data\\Photos\\</code></li><li>macOS / Linux: <code>/Users/username/uploads/</code></li></ul></li></ul><hr><h3 id="multiple-file-upload" tabindex="-1">Multiple File Upload <a class="header-anchor" href="#multiple-file-upload" aria-label="Permalink to “Multiple File Upload”">​</a></h3><p>Allows uploading multiple files into a multi-file file input in one automated step:</p><ul><li><strong>Supported Separators</strong>: <ul><li>Line break (<code>\\r\\n</code> / <code>\\n</code>)</li><li>Comma (<code>,</code>)</li><li>Semicolon (<code>;</code>)</li></ul></li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>File paths containing spaces can be enclosed in double quotes:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;C:\\Uploads\\Document 2025.pdf&quot;</span></span>
<span class="line"><span>&quot;C:\\Uploads\\Identity Card.png&quot;</span></span></code></pre></div></div><hr><h3 id="file-existence-check" tabindex="-1">File Existence Check <a class="header-anchor" href="#file-existence-check" aria-label="Permalink to “File Existence Check”">​</a></h3><ul><li><strong>Purpose</strong>: Checks whether the target file exists on your local storage before triggering the OS file dialog.</li><li><strong>Benefit</strong>: Prevents the automation from hanging on broken dialogs or attempting to open non-existent files.</li><li><strong>Recommendation</strong>: Keep this option enabled for resilient unattended automation.</li></ul><hr><h3 id="browser-window-title-customization" tabindex="-1">Browser Window Title Customization <a class="header-anchor" href="#browser-window-title-customization" aria-label="Permalink to “Browser Window Title Customization”">​</a></h3><ul><li><strong>Purpose</strong>: Specifies the exact window title of the native file selection dialog.</li><li><strong>Default Value</strong>: <code>&quot;Open&quot;</code> (standard Windows file dialog title).</li><li><strong>Use Cases</strong>: Useful when uploading via non-English operating systems, web applications with customized dialog titles (e.g. &quot;Select an image to upload&quot;), or when multiple dialogs are open simultaneously.</li></ul><hr><h2 id="handling-empty-values" tabindex="-1">Handling Empty Excel Field Values <a class="header-anchor" href="#handling-empty-values" aria-label="Permalink to “Handling Empty Excel Field Values”">​</a></h2><p>In real-world data entry, certain rows in your spreadsheet may not contain a file to upload. By default, the extension might still trigger the upload sequence, which can cause timeout warnings on blank rows.</p><h3 id="skip-empty-values" tabindex="-1">Skip Action for Empty Values <a class="header-anchor" href="#skip-empty-values" aria-label="Permalink to “Skip Action for Empty Values”">​</a></h3><p>To gracefully bypass the upload field when no file name is provided in the active spreadsheet row:</p><ol><li>In the field configuration, enable <strong>&quot;Skip field action if given field value matches&quot;</strong> (or use field condition matching).</li><li>Set the matching value pattern to <code>&#39;&#39;</code> (two single quotes representing an empty string).</li><li><strong>Execution Behavior</strong>: If the row cell is empty, the upload step is skipped entirely and automation proceeds directly to the next field.</li></ol><h3 id="empty-value-example" tabindex="-1">Configuration Example <a class="header-anchor" href="#empty-value-example" aria-label="Permalink to “Configuration Example”">​</a></h3><p><strong>Field Options Setup</strong>:</p><ul><li><strong>Set File/Folder Base Path</strong>: <code>D:\\Documents\\Uploads\\</code></li><li><strong>Skip field action if given field value matches</strong>: <code>&#39;&#39;</code></li></ul><p><strong>Execution Flow</strong>:</p><table tabindex="0"><thead><tr><th>Row</th><th>Spreadsheet Value</th><th>Execution Result</th></tr></thead><tbody><tr><td><strong>1</strong></td><td><code>document.pdf</code></td><td>Uploads <code>D:\\Documents\\Uploads\\document.pdf</code></td></tr><tr><td><strong>2</strong></td><td><em>(empty)</em></td><td>Skips upload action smoothly</td></tr><tr><td><strong>3</strong></td><td><code>photo.jpg</code></td><td>Uploads <code>D:\\Documents\\Uploads\\photo.jpg</code></td></tr><tr><td><strong>4</strong></td><td><em>(empty)</em></td><td>Skips upload action smoothly</td></tr></tbody></table><hr><h2 id="usage-examples" tabindex="-1">Common Upload Workflows <a class="header-anchor" href="#usage-examples" aria-label="Permalink to “Common Upload Workflows”">​</a></h2><h3 id="workflow-1-standard-single-file-upload" tabindex="-1">Workflow 1: Standard Single File Upload <a class="header-anchor" href="#workflow-1-standard-single-file-upload" aria-label="Permalink to “Workflow 1: Standard Single File Upload”">​</a></h3><ol><li>Enable <strong>Set File/Folder Base Path</strong> and specify your documents folder.</li><li>Enable <strong>First check that the file exists in the PC</strong>.</li><li>Keep the default window title <code>&quot;Open&quot;</code>.</li><li>In your <code>.xlsx</code> spreadsheet, populate the file names (e.g., <code>receipt_101.pdf</code>).</li></ol><h3 id="workflow-2-multi-file-batch-submission" tabindex="-1">Workflow 2: Multi-File Batch Submission <a class="header-anchor" href="#workflow-2-multi-file-batch-submission" aria-label="Permalink to “Workflow 2: Multi-File Batch Submission”">​</a></h3><ol><li>Enable <strong>Multiple File Upload</strong>.</li><li>Set the delimiter separator (e.g., newline <code>\\r\\n</code> or comma <code>,</code>).</li><li>Provide the list of file paths separated by the chosen delimiter in the Excel cell.</li></ol><h3 id="workflow-3-upload-all-files-in-a-folder" tabindex="-1">Workflow 3: Upload All Files in a Folder <a class="header-anchor" href="#workflow-3-upload-all-files-in-a-folder" aria-label="Permalink to “Workflow 3: Upload All Files in a Folder”">​</a></h3><ol><li>Enable <strong>Upload all files in a folder</strong>.</li><li>Specify the target folder path in the Base Path configuration.</li><li>The helper program reads all files in the folder and submits them collectively to the input.</li></ol><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="common-issues-solutions" tabindex="-1">Common Issues &amp; Solutions <a class="header-anchor" href="#common-issues-solutions" aria-label="Permalink to “Common Issues &amp; Solutions”">​</a></h3><table tabindex="0"><thead><tr><th>Issue</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>Helper Program not detected</strong></td><td>Program not running or blocked by firewall/antivirus</td><td>Ensure the Helper Program is running in your system tray. Check permissions and click &quot;Check File Upload Connection&quot;.</td></tr><tr><td><strong>File not found error</strong></td><td>Incorrect base path or missing file extension</td><td>Verify the directory path exists and includes the trailing slash (<code>D:\\folder\\</code>). Ensure the file extension matches the actual file on disk.</td></tr><tr><td><strong>Wrong dialog window selected</strong></td><td>Multiple file dialogs open or non-standard title</td><td>Close extraneous dialog windows. Enter the exact title in <strong>Browser Window Title</strong> matching your OS dialog.</td></tr><tr><td><strong>Upload hangs on blank rows</strong></td><td>Empty cell processed without skip condition</td><td>Configure <strong>Skip field action if given field value matches</strong> with <code>&#39;&#39;</code> to bypass rows without files.</td></tr></tbody></table><h3 id="debug-checklist" tabindex="-1">Debug Checklist <a class="header-anchor" href="#debug-checklist" aria-label="Permalink to “Debug Checklist”">​</a></h3><ol><li><strong>Verify Helper Status</strong>: Confirm the helper program icon is visible in the Windows taskbar system tray.</li><li><strong>Validate Path Manually</strong>: Copy the full path and paste it into Windows File Explorer to verify accessibility.</li><li><strong>Check Execution Logs</strong>: Open <a href="/documentation/logs.html">Logs</a> to inspect the exact resolved file path sent to the helper program.</li></ol><hr><h2 id="examples" tabindex="-1">Online Interactive Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Online Interactive Examples”">​</a></h2><p>Test and verify your upload configuration against our official interactive practice forms:</p><ul><li><a href="https://formfiller.ctechhindi.in/example/example-15.php" target="_blank" rel="noreferrer">Example-15: Single File Upload</a> - Practice single file selection and base path mapping.</li><li><a href="https://formfiller.ctechhindi.in/example/example-25.php" target="_blank" rel="noreferrer">Example-25: Multiple File Upload</a> - Practice multiple file uploads with separators.</li></ul><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/system.svg" class="doc-icon"> <a href="/documentation/program.html">Helper Program Download &amp; Setup</a></li><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field.html">Form Fields Overview</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/form-fields/field-settings.html">Field Settings</a></li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template (.xlsx)</a></li><li><img src="/svg/beaker.svg" class="doc-icon"> <a href="/documentation/logs.html">Execution Logs</a></li></ul>`,72)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};